        if entry.path().extension().and_then(|s| s.to_str()) != Some("json") { continue; }
        let bytes = fs::read(entry.path()).map_err(|_| "PiUsageReadFailed")?;
        let row: Row = serde_json::from_slice(&bytes).map_err(|_| "PiUsageInvalid")?;
